'use strict';

// MODULES //

import constantFunction from '@stdlib/utils-constant-function';
import isnan from '@stdlib/math-base-assert-is-nan';
import cos from '@stdlib/math-base-special-cos';
import PI from '@stdlib/constants-float64-pi';


// VARIABLES //

var PI_OVER_4 = PI / 4.0;


// MAIN //

/**
* Returns a function for evaluating the probability density function (PDF) for an anglit distribution with location parameter `mu` and scale parameter `sigma`.
*
* @param {number} mu - location parameter
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} PDF
*
* @example
* var pdf = factory( 0.0, 1.0 );
* var y = pdf( 0.0 );
* // returns 1.0
*
* y = pdf( 10.0 );
* // returns 0.0
*/
function factory( mu, sigma ) {
	if (
		isnan( mu ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return constantFunction( NaN );
	}
	return pdf;

	/**
	* Evaluates the probability density function (PDF) for an anglit distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {NonNegativeNumber} evaluated PDF
	*
	* @example
	* var y = pdf( 2.0 );
	* // returns <number>
	*/
	function pdf( x ) {
		var y;

		if ( isnan( x ) ) {
			return NaN;
		}

		// Transform x to the standardized form
		y = ( x - mu ) / sigma;
		if ( y < -PI_OVER_4 || y > PI_OVER_4 ) {
			return 0.0;
		}
		return cos( 2.0 * y ) / sigma;
	}
}


// EXPORTS //

export default factory;
